sys_script_client.script:
function onLoad() {
    //Type appropriate comment here, and begin script below
    var external_line = g_form.getValue('external_line_no');
    var ga = new GlideAjax('x_hsb11_mss_unst_0.MSS_Unstructured_Instruction_Client_Utils');
    ga.addParam('sysparm_name', 'updateOwningRegion');
    ga.addParam('sysparm_id', external_line);
    ga.getXMLAnswer(response);

    function response(answer) {
        var responseObj = JSON.parse(answer);
        g_form.setValue('owning_business', responseObj.business_market);
        g_form.setValue('instruction_type', responseObj.instruction_type);
    }


}
